import React, { useState } from 'react';

// Create the App component here
const App = () => {
  // Initialize controlledValue state here
  const [controlledValue, setControlledValue] = useState('');

  // Define handleControlledChange function here
  const handleControlledChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setControlledValue(e.target.value);
  };

  // Define getUncontrolledValue function here
  const getUncontrolledValue = () => {
    const input = document.getElementById('uncontrolled') as HTMLInputElement;
    if (input) {
      alert(`Uncontrolled value: ${input.value}`);
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h2>Controlled vs Uncontrolled Inputs</h2>

      <section style={{ marginBottom: '30px' }}>
        <h3>Controlled Input</h3>
        <label>
          Type here (controlled):
          <input 
            type="text" 
            value={controlledValue} 
            onChange={handleControlledChange}
            style={{ marginLeft: '10px', padding: '5px' }}
          />
        </label>
        <p style={{ marginTop: '10px' }}>
          Current controlled value: <strong>{controlledValue}</strong>
        </p>
      </section>

      <section>
        <h3>Uncontrolled Input</h3>
        <label>
          Type here (uncontrolled):
          <input 
            id="uncontrolled"
            type="text" 
            style={{ marginLeft: '10px', padding: '5px' }}
          />
        </label>
        <button 
          onClick={getUncontrolledValue}
          style={{ marginTop: '10px', padding: '8px 16px', cursor: 'pointer' }}
        >
          Read Uncontrolled Value
        </button>
      </section>
    </div>
  );
};

export default App;
